class Solution {
    public int findPeakElement(int[] nums) {
        int low = 0, high = nums.length - 1;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] > nums[mid + 1]) {
                high = mid;        // downhill: a peak is at mid or to its left
            } else {
                low = mid + 1;     // uphill: a peak is to the right
            }
        }
        return low;
    }
}

